  const jobs = pm.response.json();
  const emailJob = jobs.find((j) => j.type === 'EMAIL_SEND');
  if (!emailJob) return; // el worker puede no haber procesado el evento todavía
  pm.expect(emailJob).to.have.property('id');
  pm.expect(emailJob).to.have.property('attempt');
  pm.expect(['PROCESSING', 'RETRYING', 'COMPLETED', 'FAILED']).to.include(emailJob.status);
  pm.environment.set('emailJobId', emailJob.id);
});

