  pm.test("Status code es 200", function () { pm.response.to.have.status(200); });
  pm.test("La respuesta tiene attempt y maxAttempts", function () {
    const job = pm.response.json();
    pm.expect(job).to.have.property('attempt');
    pm.expect(job).to.have.property('maxAttempts');
  });
}
